CREATE TABLE truss.operation_configuration (original_writer_xid xid8 NOT NULL, operation_ordinal bigint NOT NULL CHECK (operation_ordinal >= 0), installation_id text NOT NULL COLLATE pg_catalog."C", source_epoch text NOT NULL COLLATE pg_catalog."C", target_incarnation text NOT NULL CHECK (octet_length(target_incarnation) BETWEEN 1 AND 1024) COLLATE pg_catalog."C", configuration_generation bigint NOT NULL CHECK (configuration_generation >= 0), key_reuse text NOT NULL CHECK (key_reuse IN ('forbid', 'allow')) COLLATE pg_catalog."C", journal_mode text NOT NULL CHECK (journal_mode IN ('engine', 'trigger')) COLLATE pg_catalog."C", original_context_sha256 bytea NOT NULL CHECK (octet_length(original_context_sha256) = 32), admission_profile_bytes bytea NOT NULL CHECK (octet_length(admission_profile_bytes) BETWEEN 1 AND 65536), configuration_bytes bytea NOT NULL CHECK (octet_length(configuration_bytes) > 0), selected_binding_bytes bytea NOT NULL CHECK (octet_length(selected_binding_bytes) > 0), installed_inventory_bytes bytea NOT NULL CHECK (octet_length(installed_inventory_bytes) > 0), configuration_sha256 bytea GENERATED ALWAYS AS (pg_catalog.sha256(configuration_bytes)) STORED, selected_binding_sha256 bytea GENERATED ALWAYS AS (pg_catalog.sha256(selected_binding_bytes)) STORED, installed_inventory_sha256 bytea GENERATED ALWAYS AS (pg_catalog.sha256(installed_inventory_bytes)) STORED, PRIMARY KEY (original_writer_xid, operation_ordinal), FOREIGN KEY (original_writer_xid, operation_ordinal) REFERENCES truss.row_home_operation (original_writer_xid, operation_ordinal), FOREIGN KEY (installation_id, source_epoch) REFERENCES truss.source_epoch_registry (installation_id, source_epoch), CHECK (((octet_length(configuration_bytes)::bigint + octet_length(selected_binding_bytes)::bigint) + octet_length(installed_inventory_bytes)::bigint) <= 16777216)); REVOKE ALL ON truss.operation_configuration FROM public